import{describe,it,expect,vi,beforeEach}from"vitest";import{VoiceAssistantController}from"../../frontend/js-modules/voice/voice-assistant-controller.js";import{ConversationContext}from"../../frontend/js-modules/voice/conversation-context.js";import{VoiceConversationHistory}from"../../frontend/js-modules/voice/voice-conversation-history.js";function fakeStorage(){const e=new Map;return{getItem:t=>e.has(t)?e.get(t):null,setItem:(t,o)=>e.set(t,o)}}const knownEntities=[{name:"Kerala",type:"destination"},{name:"Goa",type:"destination"}];function makeController(e={}){return new VoiceAssistantController({answerQuestion:e=>`Answer about: ${e}`,navigate:vi.fn(),bookmark:vi.fn(),search:vi.fn(),switchLanguage:vi.fn(),knownEntities:knownEntities,context:new ConversationContext,history:new VoiceConversationHistory({storage:fakeStorage()}),...e})}describe("VoiceAssistantController — Q&A fallback",()=>{it("routes an open-ended question to the existing Q&A engine and extracts the entity",()=>{const e=makeController(),t=e.handleTranscript("Tell me about Kerala");expect(t.intent).toBe("QA_FALLBACK"),expect(t.responseText).toContain("Kerala"),expect(e.context.getLastEntity()).toEqual({name:"Kerala",type:"destination"})})}),describe("VoiceAssistantController — navigation",()=>{it("calls navigate() with the resolved path",()=>{const e=vi.fn(),t=makeController({navigate:e}).handleTranscript("take me to the wildlife page");expect(e).toHaveBeenCalledWith("/frontend/wildlife/wildlife.html"),expect(t.navigatedTo).toBe("/frontend/wildlife/wildlife.html")})}),describe("VoiceAssistantController — multi-turn context",()=>{it('resolves "there" to the previously discussed destination for an itinerary request',()=>{const e=makeController();e.handleTranscript("Tell me about Kerala");const t=e.handleTranscript("plan a trip there for 4 days");expect(t.intent).toBe("ITINERARY"),expect(t.responseText.toLowerCase()).toContain("kerala")}),it('resolves "it" to the last entity for a bookmark request',()=>{const e=vi.fn(),t=makeController({bookmark:e});t.handleTranscript("Tell me about Goa"),t.handleTranscript("bookmark it"),expect(e).toHaveBeenCalledWith("Goa")}),it("gives an honest response when bookmarking with no known context",()=>{const e=makeController().handleTranscript("bookmark this");expect(e.responseText).toMatch(/not sure which place/i)})}),describe("VoiceAssistantController — search and language switch",()=>{it("dispatches search with the extracted query",()=>{const e=vi.fn();makeController({search:e}).handleTranscript("search for houseboats"),expect(e).toHaveBeenCalledWith("houseboats")}),it("dispatches a language switch",()=>{const e=vi.fn(),t=makeController({switchLanguage:e}).handleTranscript("switch to Hindi");expect(e).toHaveBeenCalledWith("hi"),expect(t.responseText).toMatch(/hindi/i)})}),describe("VoiceAssistantController — history and reset",()=>{it("records both the user and assistant turns",()=>{const e=makeController();e.handleTranscript("Tell me about Kerala");const t=e.history.getTurns();expect(t).toHaveLength(2),expect(t[0].speaker).toBe("user"),expect(t[1].speaker).toBe("assistant")}),it("resetConversation clears both context and history",()=>{const e=makeController();e.handleTranscript("Tell me about Kerala"),e.resetConversation(),expect(e.context.getLastEntity()).toBeNull(),expect(e.history.getTurns()).toEqual([])})});